import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
export const APP_ID = "7f3c1a2b-4d5e-4f60-8a9b-0c1d2e3f4a5b";
export const TENANT_ID = "0b1c2d3e-4f50-4a6b-9c7d-8e9f0a1b2c3d";
export const SECRET = "Q~h7.sEcReT-value_123";
const tempDirs = [];
const envKeysSet = [];
export async function removeDoctorFixtures() {
    for (const key of envKeysSet.splice(0)) {
        delete process.env[key];
    }
    for (const dir of tempDirs.splice(0)) {
        await rm(dir, { recursive: true, force: true });
    }
}
export function capture() {
    let text = "";
    const write = (chunk) => {
        text += chunk;
    };
    return { out: write, err: write, text: () => text };
}
export function fakeFetch(response) {
    const requests = [];
    const fetchImpl = async (input, init) => {
        const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
        const body = init?.body;
        requests.push({
            url,
            init,
            body: typeof body === "string"
                ? body
                : body instanceof URLSearchParams
                    ? body.toString()
                    : undefined,
        });
        return response(url);
    };
    return { fetchImpl, requests };
}
export function channelSource(meta) {
    return `import { defineChannel } from "@grok/agent-sdk/channels";

export default defineChannel({
  meta: ${meta},
  routes: [{ method: "POST", path: "/", handler: () => new Response(null, { status: 200 }) }],
});
`;
}
/** A real `teamsChannel()`, so the CLI reads the meta the SDK publishes. */
export function teamsChannelFile(options = "") {
    return `import { teamsChannel } from "@grok/agent-sdk/channels/teams";

export default teamsChannel(${options});
`;
}
export function declaredChannel(prefix) {
    return teamsChannelFile(`{ envPrefix: ${JSON.stringify(prefix)} }`);
}
/** A channel with its own credentials publishes no `credentialEnv`. */
export const OWN_CREDENTIALS_CHANNEL = teamsChannelFile(`{ credentials: { appId: "a", appPassword: "b", tenantId: "c" } }`);
export async function writeProject(folder, channels) {
    const parent = await mkdtemp(join(tmpdir(), "bdk-teams-doctor-"));
    tempDirs.push(parent);
    const dir = join(parent, folder);
    await mkdir(join(dir, "bot", "channels"), { recursive: true });
    await writeFile(join(dir, "bot", "agent.ts"), 'import { defineAgent } from "@grok/agent-sdk";\n\nexport default defineAgent({});\n');
    await writeFile(join(dir, "bot", "instructions.md"), "Teams doctor fixture.\n");
    for (const [id, source] of Object.entries(channels)) {
        await writeFile(join(dir, "bot", "channels", `${id}.ts`), source);
    }
    return dir;
}
export async function writeEnv(dir, entries) {
    const lines = Object.entries(entries).map(([key, value]) => {
        envKeysSet.push(key);
        return `${key}=${value}`;
    });
    await writeFile(join(dir, ".env.local"), `${lines.join("\n")}\n`);
}
export const HELM_APP = "11111111-1111-4111-8111-111111111111";
export const OTHER_APP = "22222222-2222-4222-8222-222222222222";
export const WIDGET_APP = "33333333-3333-4333-8333-333333333333";
export const SUBSCRIPTION = "Contoso";
export const BOT_NAME = "helm-bot";
export const BOT_GROUP = "bots";
export const AZURE_ENDPOINT = "https://bot.example.com/other-name/v1/channels/teams";
export const PUBLIC_ENDPOINT = "https://tunnel.example.com:443/other-name/v1/channels/teams";
export function botResourceId(name, resourceGroup) {
    return `/subscriptions/sub-1/resourceGroups/${resourceGroup}/providers/Microsoft.BotService/botServices/${name}`;
}
export function azNotInstalled() {
    throw Object.assign(new Error("spawn az ENOENT"), { code: "ENOENT" });
}
export function scriptedAz(reply, calls = []) {
    return async (args) => {
        calls.push([...args]);
        const result = reply(args);
        if (result === "enoent") {
            return azNotInstalled();
        }
        return { code: result.code, stdout: result.stdout, stderr: result.stderr ?? "" };
    };
}
export function tokenResponse() {
    return new Response(JSON.stringify({ access_token: "issued-token-xyz" }), { status: 200 });
}
export function jsonResponse(status, body) {
    return new Response(JSON.stringify(body), { status });
}
export async function readyProject() {
    const dir = await writeProject("other-name", { teams: declaredChannel("HELM") });
    await writeEnv(dir, {
        HELM_TEAMS_APP_ID: APP_ID,
        HELM_TEAMS_APP_PASSWORD: SECRET,
        HELM_TEAMS_TENANT_ID: TENANT_ID,
    });
    return dir;
}
export function fetchProbe(probe) {
    return fakeFetch((url) => {
        if (url.startsWith("https://login.microsoftonline.com/")) {
            return tokenResponse();
        }
        const result = probe(url);
        if (result instanceof Error) {
            throw result;
        }
        return result;
    });
}
function flagValues(args, flag) {
    const start = args.indexOf(flag);
    if (start === -1) {
        return [];
    }
    const values = [];
    for (const arg of args.slice(start + 1)) {
        if (arg.startsWith("-")) {
            break;
        }
        values.push(arg);
    }
    return values;
}
function shownResource(bot, input) {
    const id = botResourceId(bot.name, bot.resourceGroup);
    if (bot.omitProperties === true) {
        return { id, name: bot.name, resourceGroup: bot.resourceGroup };
    }
    const properties = {
        msaAppId: bot.msaAppId ?? input.msaAppId ?? APP_ID,
    };
    const endpoint = bot.endpoint ?? input.endpoint;
    if (endpoint !== undefined) {
        properties.endpoint = endpoint;
    }
    const appType = bot.msaAppType !== undefined ? bot.msaAppType : input.msaAppType;
    if (appType !== null) {
        properties.msaAppType = appType ?? "SingleTenant";
    }
    const tenant = bot.msaAppTenantId !== undefined ? bot.msaAppTenantId : input.msaAppTenantId;
    if (tenant !== null) {
        properties.msaAppTenantId = tenant ?? TENANT_ID;
    }
    return { id, name: bot.name, resourceGroup: bot.resourceGroup, properties };
}
export function loggedInBot(input) {
    const bots = input.bots ??
        (input.resources ?? [{ name: BOT_NAME, resourceGroup: BOT_GROUP }]).map((resource) => ({
            name: resource.name,
            resourceGroup: resource.resourceGroup,
        }));
    return (args) => {
        if (args[0] === "account" && args[1] === "show") {
            return { code: 0, stdout: JSON.stringify({ name: SUBSCRIPTION, id: "sub-1" }) };
        }
        if (args[0] === "resource" && args[1] === "list") {
            return {
                code: 0,
                stdout: JSON.stringify(bots.map((bot) => ({
                    id: botResourceId(bot.name, bot.resourceGroup),
                    name: bot.name,
                    resourceGroup: bot.resourceGroup,
                }))),
            };
        }
        if (args[0] === "resource" && args[1] === "show") {
            const byId = new Map(bots.map((bot) => [botResourceId(bot.name, bot.resourceGroup), bot]));
            const selected = flagValues(args, "--ids").map((id) => {
                const bot = byId.get(id);
                if (bot === undefined) {
                    throw new Error(`unexpected az resource ${id}`);
                }
                return shownResource(bot, input);
            });
            return {
                code: 0,
                stdout: JSON.stringify(selected.length === 1 ? selected[0] : selected),
            };
        }
        if (args[0] === "bot" && args[1] === "msteams") {
            if ((input.teamsCode ?? 0) !== 0) {
                return { code: input.teamsCode ?? 1, stdout: "", stderr: input.teamsStderr ?? "Not Found" };
            }
            return {
                code: 0,
                stdout: JSON.stringify({
                    properties: { properties: { isEnabled: input.teamsEnabled ?? true } },
                }),
            };
        }
        throw new Error(`unexpected az ${args.join(" ")}`);
    };
}
